package com.hongguotv.core

import org.json.JSONArray
import org.junit.Assert.*
import org.junit.Test

class PlayerSignatureTest {
    @Test fun matchesIndependentGoReferenceForBodyAndBodylessRequests() {
        // Generated by the pinned Go reference, using a fixed clock and nonce; not this signer.
        val rows = JSONArray(javaClass.getResource("/player-signing.json")!!.readText())
        for (i in 0 until rows.length()) {
            val row = rows.getJSONObject(i)
            val headers = PlayerSignature().headers(row.getString("query"),
                if (row.isNull("body")) null else row.getString("body").toByteArray(),
                row.getString("deviceId"), row.getLong("now"), hex(row.getString("nonce")))
                .mapKeys { it.key.lowercase() }
            val expected = row.getJSONObject("headers")
            expected.keys().forEach { key -> assertEquals(key, expected.getString(key), headers[key.lowercase()]) }
            assertEquals(expected.length(), headers.size)
        }
    }

    @Test fun signaturesBindBodyQueryAndRegisteredDevice() {
        val signer = PlayerSignature()
        val nonce = ByteArray(11) { it.toByte() }
        fun sign(query: String = "aid=8662&device_id=333", body: String = "{}", id: String = "333") =
            signer.headers(query, body.toByteArray(), id, 1800500000123L, nonce)
        val initial = sign()
        assertNotEquals(initial["X-Gorgon"], sign(body = "{\"video_id\":\"2\"}")["X-Gorgon"])
        assertNotEquals(initial["X-Argus"], sign(body = "{\"video_id\":\"2\"}")["X-Argus"])
        assertNotEquals(initial["X-Argus"], sign(id = "444")["X-Argus"])
        assertNotEquals(initial["X-Gorgon"], sign(query = "aid=8662&device_id=444")["X-Gorgon"])
        assertFalse(initial.containsKey("X-Medusa"))
    }
}
